class kellyslater_controller {
public:
    char pad0[12];
    entity *owner;
    char pad1[40];
    int super_state;
    char pad2[192];
    int trick_region;
    char pad3[296];
    bool end_level;
    char pad4[343];
    PhysicsObjectClass *rb;
    char pad5[3444];
    TrickManager my_trickManager;
    char pad6[8];
    ScoringManager my_scoreManager;
    char pad7[0x1AC];
    SpecialMeter specialMeter;
    char pad8[0x2C];
    spin_controller spin_ctrl;
    char pad9[140];
    int num_wipeouts;
    float ai_timer;

    entity *get_owner() { return owner; }
    bool IsAIPlayer();
    void debug_mode_play_anim();
    void process_controls(float);
    void update(float);
    int GetCurrentTrick();
    int GetTrickRegion() { return trick_region; }
    void frame_advance(time_value_t);
};

void kellyslater_controller::frame_advance(time_value_t t)
{
    get_owner()->physical->disable();

    if (debug_mode)
    {
        debug_mode_play_anim();
        return;
    }

    if (developer_options_inst->e3 && !IsAIPlayer())
    {
        if (num_wipeouts > (g_max_wipeouts - 1))
            end_level = true;
    }

    if (my_trickManager.disabled)
        ai_timer = 0.0f;
    else
        ai_timer += t;

    if (!IsAIPlayer() && ai_timer > g_test_float)
    {
        if (g_game_ptr->mode == 1 || g_game_ptr->mode == 12)
        {
            ai_timer = 0.0f;
            animation_dump.target->anim =
                g_game_ptr->players[g_game_ptr->player_num];
            animation_dump.target->table->advance(
                (char *)animation_dump.target +
                    animation_dump.target->table->adjustment,
                -1, true);
        }
    }

    if ((super_state != 3) && (super_state != 8) &&
        (super_state != 4) && (super_state != 1))
        my_trickManager.FrameAdvance(t);

    process_controls(t);
    spin_ctrl.frame_advance(t);

    if (super_state != 1)
        rb->Update(t);

    update(t);

    if (g_dump_animation_info)
    {
        ((entity_anim_tree *)get_owner()->get_anim_tree(0))
            ->debug_print_PRS_to_file();
        g_dump_animation_info = 0;
    }

    specialMeter.Update(
        t, GetTrickRegion(), GetCurrentTrick(),
        my_scoreManager.GetChain().GetTrickCount(GetCurrentTrick()));
    my_scoreManager.Update(t);
}
